  T.check('W6 stderr is prefixed nanojira: (or nanojira-mcp:), names "too old" AND the minimum version 24 -- not just exit 127 (sh\'s own "No such file" also exits 127)',
    /^(nanojira|nanojira-mcp): .*too old/.test(r.stderr) && /24/.test(r.stderr), J(r.stderr));
