/* ===================================================================== */
/* W13 (optional, DECISIONS 185 addendum 9b3d0de) -- the exported bundle  */
/* imports only node:* built-ins, nothing from node_modules, enforced at */
/* build time per the addendum -- checked here by scanning the SHIPPED   */
/* bundle's own static import/require specifiers, a best-effort textual  */
/* scan (not a full parse), against the exported dist/*.mjs directly.    */
/* ===================================================================== */
{
  function nonNodeImports(file: string) {
    if (!fs.existsSync(file)) return null;
    const src = fs.readFileSync(file, 'utf8');
    const specifiers = new Set<string>();
    const importRe = /\bimport\s+(?:[^'"]*?\sfrom\s+)?["']([^"']+)["']/g;
    const requireRe = /\brequire\(\s*["']([^"']+)["']\s*\)/g;
    let m;
    while ((m = importRe.exec(src))) specifiers.add(m[1]);
    while ((m = requireRe.exec(src))) specifiers.add(m[1]);
    return [...specifiers].filter(s => !s.startsWith('node:') && !s.startsWith('.') && !s.startsWith('/'));
  }
  const bad = nonNodeImports(path.join(DEST, 'dist', 'nanojira.mjs'));
  T.check('W13 (optional) dist/nanojira.mjs imports nothing but node:* built-ins', bad !== null && bad.length === 0, bad === null ? 'dist/nanojira.mjs does not exist' : J(bad));
  const badMcp = nonNodeImports(path.join(DEST, 'dist', 'nanojira-mcp.mjs'));
  T.check('W13 (optional) dist/nanojira-mcp.mjs imports nothing but node:* built-ins', badMcp !== null && badMcp.length === 0, badMcp === null ? 'dist/nanojira-mcp.mjs does not exist' : J(badMcp));
}

/* ===================================================================== */
/* W14 -- every shipped file comes from the TAG's own tree, never the     */
/* working tree, even after the working tree has moved past the tag:     */
/* tamper dist/nanojira.mjs, SKILL.md and package.json's version in the fixture */
/* repo, commit that tamper (HEAD now differs from GOOD_TAG), then export */
/* GOOD_TAG again and confirm SKILL.md/bin/dist byte-identical to         */
/* `git show GOOD_TAG:<path>` -- not to any of the post-tag changes, and  */
/* still no VERSION file. Compared as Buffers, not strings: a real byte-  */
/* identity check, not a text/encoding-tolerant one.                      */
/* ===================================================================== */
{
  function showBuf(ref: string) {
    return spawnSync('git', ['show', ref], { cwd: REPO }).stdout;
  }
  const tagSkillMd = showBuf(GOOD_TAG + ':SKILL.md');
  const tagDistNj = showBuf(GOOD_TAG + ':dist/nanojira.mjs');
  const tagBinNj = showBuf(GOOD_TAG + ':bin/nanojira');
  const tagLicense = showBuf(GOOD_TAG + ':LICENSE');
  const tagPkgVersion = JSON.parse(showBuf(GOOD_TAG + ':package.json').toString('utf8')).version;

  fs.appendFileSync(path.join(REPO, 'dist', 'nanojira.mjs'), '\n// post-tag tamper, must never be exported\n');
  fs.appendFileSync(path.join(REPO, 'SKILL.md'), '\npost-tag tamper, must never be exported\n');
  if (fs.existsSync(path.join(REPO, 'bin', 'nanojira'))) fs.appendFileSync(path.join(REPO, 'bin', 'nanojira'), '\n# post-tag tamper\n');
  if (fs.existsSync(path.join(REPO, 'LICENSE'))) fs.appendFileSync(path.join(REPO, 'LICENSE'), '\npost-tag tamper, must never be exported\n');
  const pkg = JSON.parse(fs.readFileSync(path.join(REPO, 'package.json'), 'utf8'));
  pkg.version = '9.9.9-posttag';
  fs.writeFileSync(path.join(REPO, 'package.json'), JSON.stringify(pkg, null, 2) + '\n');
  const git = (args: string[]) => spawnSync('git', args, { cwd: REPO, encoding: 'utf8' });
  git(['add', '-A']);
  const commit = git(['commit', '-q', '-m', 'post-tag tamper -- must not leak into an export of ' + GOOD_TAG]);
  T.check('W14 fixture: a commit after the tag, moving HEAD past GOOD_TAG', commit.status === 0, commit.stderr);

  const dest = path.join(H.freshDir('ac56-dest-posttag'), 'exported');
  const r = runExport([GOOD_TAG, dest], REPO);
  T.check('W14 export of GOOD_TAG still exits 0 after the working tree moved past it', r.status === 0, 'status=' + r.status + ' stderr=' + J(r.stderr));
  const gotSkillMd = fs.existsSync(path.join(dest, 'SKILL.md')) ? fs.readFileSync(path.join(dest, 'SKILL.md')) : null;
  T.check('W14 exported SKILL.md is byte-identical to the TAG\'s tree, not the tampered working tree',
    gotSkillMd !== null && gotSkillMd.equals(tagSkillMd), dest);
  const gotDistNj = fs.existsSync(path.join(dest, 'dist', 'nanojira.mjs')) ? fs.readFileSync(path.join(dest, 'dist', 'nanojira.mjs')) : null;
  T.check('W14 exported dist/nanojira.mjs is byte-identical to the TAG\'s tree, not the tampered working tree',
    gotDistNj !== null && gotDistNj.equals(tagDistNj), dest);
  const gotBinNj = fs.existsSync(path.join(dest, 'bin', 'nanojira')) ? fs.readFileSync(path.join(dest, 'bin', 'nanojira')) : null;
  T.check('W14 exported bin/nanojira is byte-identical to the TAG\'s tree, not the tampered working tree',
    tagBinNj.length === 0 ? gotBinNj === null : (gotBinNj !== null && gotBinNj.equals(tagBinNj)), dest);
  const gotLicense = fs.existsSync(path.join(dest, 'LICENSE')) ? fs.readFileSync(path.join(dest, 'LICENSE')) : null;
  T.check('W14 exported LICENSE is byte-identical to the TAG\'s tree, not the tampered working tree',
    tagLicense.length === 0 ? gotLicense === null : (gotLicense !== null && gotLicense.equals(tagLicense)), dest);
  T.check('W14 the export still has no VERSION file', !fs.existsSync(path.join(dest, 'VERSION')), dest);
  T.check('W14 (fixture sanity) the tag\'s own package.json version is NOT the tampered 9.9.9-posttag',
    tagPkgVersion !== '9.9.9-posttag', tagPkgVersion);
}

/* ===================================================================== */
/* W15 -- NODE_OPTIONS is unset before exec, for both bin/nanojira and          */
/* bin/nanojira-mcp: an inherited --require hook that would otherwise fire on  */
/* every node invocation must never run. Checked by actually writing a   */
/* marker file from the hook -- its absence is the only thing that       */
/* proves NODE_OPTIONS never reached node, not merely that the call       */
/* "worked" (which it would either way: requiring the hook does not      */
/* itself fail).                                                         */
/* ===================================================================== */
{
  const markerDir = H.freshDir('ac56-node-options');
  const marker = path.join(markerDir, 'marker');
  const hook = path.join(markerDir, 'hook.js');
  fs.writeFileSync(hook, 'require(\'fs\').writeFileSync(' + JSON.stringify(marker) + ', \'fired\\n\');\n');
  for (const bin of ['nanojira', 'nanojira-mcp']) {
    if (fs.existsSync(marker)) fs.rmSync(marker);
    const r = runWrapper(path.join(DEST, 'bin', bin), ['--version'], { env: { NODE_OPTIONS: '--require=' + hook } });
    T.check('W15 ' + bin + ' --version with NODE_OPTIONS=--require=<hook>: exit 0',
      r.status === 0, 'status=' + r.status + ' stderr=' + J(r.stderr));
    T.check('W15 ' + bin + ': the --require hook never fired (NODE_OPTIONS unset before exec)',
      !fs.existsSync(marker), marker);
  }
}

/* ===================================================================== */
/* W16 -- the version floor is exactly 24, not merely "double-digit": a   */
/* stub one minor below (23.9.0) is rejected exactly like W6's v10.2.0,  */
/* and a stub at exactly the floor (24.0.0) is accepted -- the earlier    */
/* W6 leg alone could not tell a "< 24" floor apart from a "< 10" one.    */
/* ===================================================================== */
{
  function stubNode(version: string) {
    const dir = H.freshDir('ac56-node-stub-' + version.replace(/[^0-9a-zA-Z]/g, '-'));
    const stub = path.join(dir, 'node');
    fs.writeFileSync(stub,
      '#!/bin/sh\ncase "$1" in\n  --version) echo "v' + version + '"; exit 0 ;;\n  *) exec "' + process.execPath + '" "$@" ;;\nesac\n');
    fs.chmodSync(stub, 0o755);
    return stub;
  }
  {
    const stub = stubNode('23.9.0');
    const r = runWrapper(path.join(DEST, 'bin', 'nanojira'), ['--version'], { env: { NJ_NODE: stub } });
    T.check('W16 NJ_NODE=<node v23.9.0>: exit 127 (the floor is exactly 24, one minor below is still too old)',
      r.status === 127, 'status=' + r.status + ' stdout=' + J(r.stdout) + ' stderr=' + J(r.stderr));
    T.check('W16 v23.9.0 stderr names "too old" and the minimum version 24',
      /^(nanojira|nanojira-mcp): .*too old/.test(r.stderr) && /24/.test(r.stderr), J(r.stderr));
  }
  {
    const stub = stubNode('24.0.0');
    const r = runWrapper(path.join(DEST, 'bin', 'nanojira'), ['--version'], { env: { NJ_NODE: stub } });
    T.check('W16 NJ_NODE=<node v24.0.0>: accepted, exit 0 (exactly at the floor, not "too old")',
      r.status === 0, 'status=' + r.status + ' stdout=' + J(r.stdout) + ' stderr=' + J(r.stderr));
    T.check('W16 v24.0.0 reports the exported version', r.stdout.indexOf(REAL_PKG_VERSION) !== -1, r.stdout);
  }
}

/* ===================================================================== */
/* W8 -- nanojira-mcp still finds its dist/nanojira.mjs sibling under this layout    */
/* (the D179 sibling-by-extension rule, exercised against the EXPORTED   */
/* dist/ folder directly, independent of the sh wrapper)                 */
/* ===================================================================== */
(async () => {
  const distNj = path.join(DEST, 'dist', 'nanojira.mjs');
  const distNjMcp = path.join(DEST, 'dist', 'nanojira-mcp.mjs');
  const haveBoth = fs.existsSync(distNj) && fs.existsSync(distNjMcp);

  if (!haveBoth) {
    T.check('W8 fixture: the exported dist/nanojira.mjs and dist/nanojira-mcp.mjs exist (export did not run)', false, 'DEST=' + DEST);
    T.check('W9 fixture: cannot check the version against an export that was never built', false, 'DEST=' + DEST);
  } else {
    const bl = path.join(H.freshDir('ac56-mcp-backlog'), 'backlog');
    const init = spawnSync(process.execPath, [distNj, 'init', '--backlog=' + bl], { encoding: 'utf8' });
    T.check('W8 fixture: nanojira init against the exported dist/nanojira.mjs', init.status === 0, init.stderr);

    const s = MCP.spawnServer(distNjMcp, ['--backlog=' + bl]);
    try {
      const r = await s.modernToolsCall('doctor', {});
      T.check('W8 nanojira-mcp (exported) tools/call doctor: no protocol error', !r.error, J(r.error));
      T.check('W8 nanojira-mcp (exported) tools/call doctor: got a result (spawned its dist/nanojira.mjs sibling)',
        !!(r.result), J(r));
    } finally {
      await s.close();
    }

    /* ===================================================================== */
    /* W9 -- the exported SKILL.md's metadata.version equals the exported    */
    /* nanojira's own --version (no VERSION file any more to check instead)        */
    /* ===================================================================== */
    const skillMdExported = fs.existsSync(path.join(DEST, 'SKILL.md')) ? fs.readFileSync(path.join(DEST, 'SKILL.md'), 'utf8') : null;
    const mv = skillMdExported ? /^metadata:\s*\n\s*version:\s*"([^"]+)"/m.exec(skillMdExported) : null;
    const skillVersion = mv ? mv[1] : null;
    const vr = spawnSync(process.execPath, [distNj, '--version', '--json'], { encoding: 'utf8' });
    let vj = null; try { vj = JSON.parse(vr.stdout); } catch (e) { /* left null */ }
    T.check('W9 the exported SKILL.md\'s metadata.version equals the exported nanojira --version', !!vj && skillVersion !== null && vj.version === skillVersion, J(vj) + ' vs SKILL.md metadata.version=' + J(skillVersion));
    T.check('W9 that also equals package.json\'s version', skillVersion === REAL_PKG_VERSION, skillVersion + ' vs ' + REAL_PKG_VERSION);
  }

  T.finish();
})();
